"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[5553],{5366:e=>{e.exports=JSON.parse('{"label":"components","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/tags/components","allTagsPath":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/tags","count":4,"items":[{"id":"version-1.0/assets-handling","title":"Assets handling","description":"Assets exist on the base layer, which is where they have actual meaning and value. As with any execution layer solution, a Cartesi dApp that wants to manipulate assets (e.g. to allow players to bet on a game, so that the winner receives the loser\'s assets) needs a secure way of \\"teleporting\\" the assets from the base layer to the execution layer, and then a way to \\"teleport\\" them back to the base layer.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/assets-handling"},{"id":"version-1.0/main-concepts","title":"Main concepts","description":"As explained in the previous section, the Cartesi Rollups framework achieves scalability by moving the bulk of the computation outside the blockchain, using the ledger as a data source but not as an execution environment. As such, the solution contains both on-chain (L1) and off-chain (L2) components.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/main-concepts"},{"id":"version-1.0/reading-outputs","title":"Reading outputs","description":"In Cartesi Rollups, the outputs include:","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/reading-outputs"},{"id":"version-1.0/sending-requests","title":"Sending requests","description":"In Cartesi Rollups, there are two kinds of requests that can be made to the dApp:","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/sending-requests"}]}')}}]);